insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_absorb','absorb','verb','to take in and understand information or knowledge','[{"senseId":"absorb_1","meaning":"to take in and understand information or knowledge","acceptedParaphrases":["take in and understand","learn and take in"],"masteryContexts":[{"contextId":"u6_01_absorb_meaning","text":"Students who read slowly and make notes absorb far more from a chapter than those who only turn the pages.","meaning":"to take in and understand information","wrongMeanings":["to copy information from a source exactly","to remember information only for a test","to give information to other students"]},{"contextId":"u6_01_absorb_paraphrase","text":"During her first months in a new country, children often absorb the rhythm of the language without ever opening a grammar book.","meaning":"to take in knowledge gradually and naturally","wrongMeanings":["to practise knowledge in a formal lesson","to test knowledge by asking questions","to share knowledge with other learners"]}],"situationDistractors":["The teacher handed out the worksheets, and the class waited quietly for the bell to ring.","He closed the textbook, switched on the television and decided to start revising the next day.","A student copied a paragraph word for word and handed it in without reading it.","The librarian stamped the returned books and put them back on the shelves.","Mia spent an hour arranging her desk, but she never opened her notebook.","The class were asked to hand in their homework at the start of the lesson."],"gapDistractors":[{"contextId":"u6_01_absorb_gap_1","answer":"absorb","wrong":["skip","reject","postpone"]},{"contextId":"u6_01_absorb_gap_2","answer":"absorb","wrong":["ignore","invent","refuse"]},{"contextId":"u6_01_absorb_gap_3","answer":"absorb","wrong":["correct","erase","interrupt"]}],"spellingErrors":["absorbe","abzorb","absorbb","absob","absorbt","absorp"],"masteryPassages":[{"passageId":"u6_01_absorb_passage_1","contextId":"u6_01_absorb_gap_1","text":"Before an exam, some students read their notes again and again without stopping to think. Others pause after every page, because they find it easier to ____ the main ideas when they study in short sections.","answer":"absorb"},{"passageId":"u6_01_absorb_passage_2","contextId":"u6_01_absorb_gap_2","text":"The new pupils arrived with very little English. After a term of listening to their classmates and watching lessons, they began to ____ the language without even trying.","answer":"absorb"}],"contextDependentParaphrases":[],"wrongParaphrases":["write down and check","read aloud and repeat","look at and ignore"],"misleadingDistractors":["to copy information exactly from a book","to avoid learning new information","to forget information after a short time"],"teacherNote":"Taught in its learning sense: to take in and understand information or knowledge. Boundary: absorb is taking information in; process is working on it in your mind. The physical sense (a sponge absorbs water) is not taught here."}]'::jsonb,'[]'::jsonb,'["absorb information","absorb new ideas","absorb knowledge"]'::jsonb,'live'),
('vocab_confidence','confidence','noun','belief in your own ability or judgement','[{"senseId":"confidence_1","meaning":"belief in your own ability or judgement","acceptedParaphrases":["belief in yourself","trust in your own ability"],"masteryContexts":[{"contextId":"u6_02_confidence_meaning","text":"After three successful presentations, Omar spoke with far more confidence than he had at the start of the term.","meaning":"belief in your own ability","wrongMeanings":["fear of speaking in front of other people","respect for the opinions of other people","interest in the work of other people"]},{"contextId":"u6_02_confidence_paraphrase","text":"Praise from the teacher gave the shy student the confidence to put her hand up and give her opinion.","meaning":"belief that you are able to do something well","wrongMeanings":["worry that you may make a mistake","certainty that your answer is correct","permission to speak in front of the class"]}],"situationDistractors":["The class waited outside the room while the invigilator checked the exam papers.","A girl tore up her notes after the teacher announced that the test had been cancelled.","The student whispered his answer so quietly that nobody could hear it, and he stared at the floor.","The students lined up in the corridor and waited for the exam hall to open.","Tariq packed his pencil case, his calculator and a bottle of water into his bag.","The teacher wrote the date and the title of the lesson on the board."],"gapDistractors":[{"contextId":"u6_02_confidence_gap_1","answer":"confidence","wrong":["information","homework","permission"]},{"contextId":"u6_02_confidence_gap_2","answer":"confidence","wrong":["frustration","handwriting","height"]},{"contextId":"u6_02_confidence_gap_3","answer":"confidence","wrong":["weight","sleep","temper"]}],"spellingErrors":["confidance","confedence","confidense","confidnce","conffidence","confindence"],"wordFamilyForms":[{"form":"confidence","partOfSpeech":"noun","example":"Regular practice gives learners the confidence to speak in front of the class.","pedagogicallyUseful":true},{"form":"confident","partOfSpeech":"adjective","example":"She felt confident about the exam because she had revised every topic.","pedagogicallyUseful":true,"altExample":"Learners who practise every day soon become confident speakers."},{"form":"confidently","partOfSpeech":"adverb","example":"He answered the examiner’s questions confidently and without notes.","pedagogicallyUseful":true,"altExample":"After weeks of rehearsal, the team presented their project confidently."}],"masteryPassages":[{"passageId":"u6_02_confidence_passage_1","contextId":"u6_02_confidence_gap_1","text":"Karim used to be afraid of speaking in class, and he avoided every presentation. After a term of small speaking tasks with a friendly partner, he spoke with far more ____ and even volunteered to lead a debate.","answer":"confidence"},{"passageId":"u6_02_confidence_passage_2","contextId":"u6_02_confidence_gap_2","text":"A teacher’s praise can change the way a student feels about a subject. When Elena heard that her essay was one of the best, she gained the ____ to try harder tasks and to share her opinion in class.","answer":"confidence"}],"contextDependentParaphrases":[],"wrongParaphrases":["fear of failure","respect for others","interest in a subject"],"misleadingDistractors":["complete certainty that a fact is true","worry about an important test","respect for a teacher or a school"],"teacherNote":"Confidence is belief in your own ability or judgement. It is not the same as certainty that a fact is true (I am certain that Paris is the capital of France)."}]'::jsonb,'["confident","confidently"]'::jsonb,'["build confidence","lack confidence","confidence in your own ability"]'::jsonb,'live'),
('vocab_dilemma','dilemma','noun','a situation in which you must make a difficult choice between two or more options','[{"senseId":"dilemma_1","meaning":"a situation in which you must make a difficult choice between two or more options","acceptedParaphrases":["difficult choice","hard decision"],"masteryContexts":[{"contextId":"u6_03_dilemma_meaning","text":"Hana faced a dilemma: she could revise alone for the exam or help her friend, who had missed three lessons.","meaning":"a difficult choice between two options","wrongMeanings":["a serious mistake that cannot be corrected","an argument between two close friends","a disappointing result in an examination"]},{"contextId":"u6_03_dilemma_paraphrase","text":"The headteacher was in a dilemma, because cancelling the trip would disappoint the pupils but going ahead would be unsafe in the storm.","meaning":"a situation in which every choice has a disadvantage","wrongMeanings":["a situation in which a plan has been cancelled","a situation in which two groups disagree","a situation in which a promise has been broken"]}],"situationDistractors":["The students arrived early and found that the classroom door was already open.","Layla checked her answers twice and handed in the paper before the bell.","The teacher explained the instructions slowly and then asked the class to begin.","Aisha found her lost notebook under a pile of papers and put it back in her bag.","The school bus arrived on time and the pupils climbed on board.","The students copied the homework from the board and left when the bell rang."],"gapDistractors":[{"contextId":"u6_03_dilemma_gap_1","answer":"dilemma","wrong":["argument","mistake","schedule"]},{"contextId":"u6_03_dilemma_gap_2","answer":"dilemma","wrong":["pleasure","success","reward"]},{"contextId":"u6_03_dilemma_gap_3","answer":"dilemma","wrong":["holiday","success","tradition"]}],"spellingErrors":["dilema","dillemma","dilemna","dilemmar","dillema","dilemmer"],"masteryPassages":[{"passageId":"u6_03_dilemma_passage_1","contextId":"u6_03_dilemma_gap_1","text":"Zara has been offered a place on a summer science course, but it starts in the same week as her cousin’s wedding abroad. She cannot attend both, so she is in a real ____ and has asked her teacher for advice.","answer":"dilemma"},{"passageId":"u6_03_dilemma_passage_2","contextId":"u6_03_dilemma_gap_2","text":"Should he report a classmate who had cheated, or stay loyal to a friend? Nobody could tell Daniel what to do, and he spent the whole weekend thinking about this ____ without finding an answer that felt right.","answer":"dilemma"}],"contextDependentParaphrases":[],"wrongParaphrases":["simple answer","sudden change","private opinion"],"misleadingDistractors":["a serious problem that has no solution","a disagreement between two friends","a mistake that is made by accident"],"teacherNote":"A dilemma is a difficult choice between alternatives, where each choice has a disadvantage. It is not simply “a problem”."}]'::jsonb,'[]'::jsonb,'["face a dilemma","moral dilemma","solve a dilemma"]'::jsonb,'live'),
('vocab_dramatically','dramatically','adverb','to a very great or noticeable degree','[{"senseId":"dramatically_1","meaning":"to a very great or noticeable degree","acceptedParaphrases":["to a very great extent","in a very noticeable way"],"masteryContexts":[{"contextId":"u6_04_dramatically_meaning","text":"Reading habits have changed dramatically since the arrival of smartphones, and many teenagers now read short texts instead of books.","meaning":"to a very great and noticeable degree","wrongMeanings":["in a way that is easy to predict","in a slow and steady way","in a way that only experts notice"]},{"contextId":"u6_04_dramatically_paraphrase","text":"Her marks improved dramatically after she began to revise every evening, rising from forty to eighty-five per cent.","meaning":"by a very large and noticeable amount","wrongMeanings":["by a very small and gradual amount","by an amount that nobody measures","by an amount that stays the same"]}],"situationDistractors":["The school timetable changed slightly, and the first lesson now starts five minutes later.","Marks stayed almost exactly the same from one term to the next.","The students walked quietly to the hall and sat in rows.","The headteacher read the notices aloud, and the assembly lasted twenty minutes as usual.","Every pupil in the class received the same book and the same worksheet.","The teacher moved the clock to the other wall, and nobody noticed the difference."],"gapDistractors":[{"contextId":"u6_04_dramatically_gap_1","answer":"dramatically","wrong":["slightly","rarely","secretly"]},{"contextId":"u6_04_dramatically_gap_2","answer":"dramatically","wrong":["barely","politely","occasionally"]},{"contextId":"u6_04_dramatically_gap_3","answer":"dramatically","wrong":["slightly","neatly","quietly"]}],"spellingErrors":["dramaticly","dramaticaly","dramatikally","dramaticlly","dramatticaly","dramatcally"],"masteryPassages":[{"passageId":"u6_04_dramatically_passage_1","contextId":"u6_04_dramatically_gap_1","text":"Twenty years ago, most students wrote their essays by hand. Today almost all of them use laptops, so the way young people write has changed ____ in a single generation.","answer":"dramatically"},{"passageId":"u6_04_dramatically_passage_2","contextId":"u6_04_dramatically_gap_2","text":"The new head teacher moved the start of lessons from eight o’clock to nine. Absences fell ____, and within a month the number of late students dropped from forty a week to just three.","answer":"dramatically"}],"contextDependentParaphrases":[],"wrongParaphrases":["to a very small extent","at a very fast speed","in a very careful way"],"misleadingDistractors":["in a calm and quiet way","in a slow and careful way","for a very short time"],"teacherNote":"An adverb of degree and change: it says that something changed by a very large, noticeable amount (rose dramatically, changed dramatically). It is not the same as “like a play” or “suddenly”."}]'::jsonb,'[]'::jsonb,'["change dramatically","increase dramatically","improve dramatically"]'::jsonb,'live'),
('vocab_equivalent','equivalent','adjective','equal in value, meaning, amount or function','[{"senseId":"equivalent_1","meaning":"equal in value, meaning, amount or function","acceptedParaphrases":["equal in value","equal in function"],"masteryContexts":[{"contextId":"u6_05_equivalent_meaning","text":"Many universities accept a recognised foreign qualification that is equivalent to the national school certificate.","meaning":"equal in value or level","wrongMeanings":["higher in value or level","recognised in only one country","similar in appearance or style"]},{"contextId":"u6_05_equivalent_paraphrase","text":"Some teachers claim that one hour of focused study is equivalent to two hours of study with a phone nearby.","meaning":"equal in value or effect","wrongMeanings":["greater in value or effect","smaller in value or effect","different in value or effect"]}],"situationDistractors":["Hamid chose the harder paper because he wanted to challenge himself in the final exam.","One school has a hundred students and the other has a thousand, so their budgets are very different.","The teacher gave the best essay a higher mark than all the others.","The new student was given a locker, a timetable and a map of the school.","The science fair was held in the sports hall, and parents came to see the projects.","A parcel of textbooks arrived at the school office on Wednesday morning."],"gapDistractors":[{"contextId":"u6_05_equivalent_gap_1","answer":"equivalent","wrong":["superior","unrelated","opposite"]},{"contextId":"u6_05_equivalent_gap_2","answer":"equivalent","wrong":["unequal","different","separate"]},{"contextId":"u6_05_equivalent_gap_3","answer":"equivalent","wrong":["superior","inferior","unrelated"]}],"spellingErrors":["equivelent","equivalant","equivilent","equivalet","equivalnet","equivallent"],"masteryPassages":[{"passageId":"u6_05_equivalent_passage_1","contextId":"u6_05_equivalent_gap_1","text":"Maria moved from Spain to England in the middle of her school career. The English school asked for proof that her Spanish certificate was ____ to the one they usually accepted, and only then did they allow her to join the sixth form.","answer":"equivalent"},{"passageId":"u6_05_equivalent_passage_2","contextId":"u6_05_equivalent_gap_2","text":"Both holiday courses cost four hundred pounds and last two weeks, and they cover the same topics. The brochure says that the two courses are completely ____, so students may choose whichever is closer to home.","answer":"equivalent"}],"contextDependentParaphrases":[],"wrongParaphrases":["greater in size","different in kind","lower in rank"],"misleadingDistractors":["similar in some ways but not equal in value","higher in value than something else","completely different in every way"],"teacherNote":"Equivalent means equal in value, amount, meaning or function (usually followed by “to”). It is stronger than similar: two similar things resemble each other, two equivalent things count as equal."}]'::jsonb,'[]'::jsonb,'["roughly equivalent","equivalent to","an equivalent qualification"]'::jsonb,'live'),
('vocab_overload','overload','verb','to give someone or something more work or information than they can deal with','[{"senseId":"overload_1","meaning":"to give someone or something more work or information than they can deal with","acceptedParaphrases":["give too much work to","ask too much of"],"masteryContexts":[{"contextId":"u6_06_overload_meaning","text":"Teachers should not overload students with extra assignments during the week of the mock examinations.","meaning":"to give someone more work than they can manage","wrongMeanings":["to give someone extra help with their work","to give someone a reward for hard work","to give someone work that is much too easy"]},{"contextId":"u6_06_overload_paraphrase","text":"If you overload your memory with too many facts the night before an exam, you will remember very little in the morning.","meaning":"to give your mind more information than it can deal with","wrongMeanings":["to give your mind a rest before it works again","to teach your mind to remember facts accurately","to keep your mind free from all information"]}],"situationDistractors":["The teacher reduced the homework for the week so that students could rest after the exams.","A student wrote a neat summary of each chapter and kept the pages in a folder.","The class finished the experiment ten minutes early and tidied the laboratory.","The students tidied the art room and washed the brushes before leaving.","The teacher gave back the marked essays and explained the grading criteria.","Sara borrowed three novels from the library and finished them over the holiday."],"gapDistractors":[{"contextId":"u6_06_overload_gap_1","answer":"overload","wrong":["supply","reward","test"]},{"contextId":"u6_06_overload_gap_2","answer":"overload","wrong":["shorten","cancel","delay"]},{"contextId":"u6_06_overload_gap_3","answer":"overload","wrong":["empty","shorten","print"]}],"spellingErrors":["overlode","overlod","overloade","overlaod","ovreload","overlowd"],"masteryPassages":[{"passageId":"u6_06_overload_passage_1","contextId":"u6_06_overload_gap_1","text":"In the final term, some teachers set an essay, a project and three tests in a single week. Students became exhausted and anxious, so the head of year asked staff not to ____ them with work.","answer":"overload"},{"passageId":"u6_06_overload_passage_2","contextId":"u6_06_overload_gap_2","text":"Making a good revision timetable means being realistic. If you try to ____ every day with six subjects and no breaks, you will feel exhausted by Wednesday and give up by Friday.","answer":"overload"}],"contextDependentParaphrases":[],"wrongParaphrases":["give a short break to","give a clear answer to","give a good mark to"],"misleadingDistractors":["to give someone a short break from study","to give someone the correct answers in advance","to give someone less work than they would like"],"teacherNote":"The verb overload means to give someone or something more work or information than can be handled effectively; the learning context is the main one (overload students with homework, overload your memory)."}]'::jsonb,'[]'::jsonb,'["overload students","overload with information","overload the system"]'::jsonb,'live'),
('vocab_stagnate','stagnate','verb','to stop developing, improving or making progress','[{"senseId":"stagnate_1","meaning":"to stop developing, improving or making progress","acceptedParaphrases":["stop improving","fail to make progress"],"masteryContexts":[{"contextId":"u6_07_stagnate_meaning","text":"Her marks began to stagnate in the second year, even though she was studying just as hard as before.","meaning":"to stop making progress","wrongMeanings":["to get worse very quickly","to make progress in some subjects only","to start making progress again"]},{"contextId":"u6_07_stagnate_paraphrase","text":"If a business stops introducing new ideas, its sales will stagnate while its competitors grow.","meaning":"to stop developing or growing","wrongMeanings":["to develop in an unexpected direction","to grow much faster than a rival","to change into a different business"]}],"situationDistractors":["The student’s marks rose steadily in every test during the autumn term.","The new teacher gave the class a different project every fortnight, and everyone wanted to take part.","The headteacher announced the date of the next parents’ evening in the school newsletter.","The students planted vegetables in the school garden and watered them every morning.","The language club moved to a larger room because more pupils wanted to join.","The teacher showed a short film about the history of the town."],"gapDistractors":[{"contextId":"u6_07_stagnate_gap_1","answer":"stagnate","wrong":["advance","celebrate","compete"]},{"contextId":"u6_07_stagnate_gap_2","answer":"stagnate","wrong":["accelerate","expand","return"]},{"contextId":"u6_07_stagnate_gap_3","answer":"stagnate","wrong":["flourish","expand","celebrate"]}],"spellingErrors":["stagnat","stagnait","stagnete","stangate","stagante","stagnatte"],"wordFamilyForms":[{"form":"stagnate","partOfSpeech":"verb","example":"Without new challenges, even a talented student may stagnate.","pedagogicallyUseful":true},{"form":"stagnation","partOfSpeech":"noun","example":"After a long period of economic stagnation, the government introduced new policies to create jobs.","pedagogicallyUseful":true,"altExample":"Teachers worried about the stagnation in test scores over the past three years."},{"form":"stagnant","partOfSpeech":"adjective","example":"Wages stayed stagnant for years, even though prices continued to rise.","pedagogicallyUseful":true,"altExample":"A stagnant routine can make revision feel pointless."}],"masteryPassages":[{"passageId":"u6_07_stagnate_passage_1","contextId":"u6_07_stagnate_gap_1","text":"Many learners reach an intermediate level and then feel that they are not moving forward. If they keep repeating the same exercises, they are likely to ____, while those who try harder tasks carry on improving.","answer":"stagnate"},{"passageId":"u6_07_stagnate_passage_2","contextId":"u6_07_stagnate_gap_2","text":"The village once had a busy market, a school and a railway station. After the railway closed, no new families arrived, and for twenty years the whole community seemed to ____.","answer":"stagnate"}],"contextDependentParaphrases":[],"wrongParaphrases":["improve too quickly","change direction","become more difficult"],"misleadingDistractors":["to improve quickly","to become more difficult","to start again from the beginning"],"teacherNote":"Stagnate means to stop developing or improving, often for a long time. It is usually a negative word (stagnating results, a stagnating economy)."}]'::jsonb,'["stagnation","stagnant"]'::jsonb,'["begin to stagnate","results stagnate","progress stagnates"]'::jsonb,'live'),
('vocab_engage','engage','verb','to become involved and interested in an activity, especially in learning','[{"senseId":"engage_1","meaning":"to become involved and interested in an activity, especially in learning","acceptedParaphrases":["become involved","take a real interest"],"masteryContexts":[{"contextId":"u6_08_engage_meaning","text":"Interactive tasks help shy students to engage with the topic instead of just listening to the teacher.","meaning":"to become involved and interested","wrongMeanings":["to listen politely without taking part","to leave a task as soon as it is difficult","to make notes for another person"]},{"contextId":"u6_08_engage_paraphrase","text":"It is hard to engage with a long article if you do not care about its subject.","meaning":"to take a real interest and get involved","wrongMeanings":["to read quickly and move on","to copy the main points of the text","to avoid the subject if it is difficult"]}],"situationDistractors":["The student sat at the back and looked out of the window until the bell rang.","The librarian locked the door at six o’clock and switched off the lights.","The teacher marked the books at the weekend and returned them on Monday.","The cleaner mopped the corridor while the pupils were having lunch.","The teacher took the register and then handed out the exercise books.","Late in the afternoon, the students packed their bags and went home on the bus."],"gapDistractors":[{"contextId":"u6_08_engage_gap_1","answer":"engage","wrong":["believe","result","succeed"]},{"contextId":"u6_08_engage_gap_2","answer":"engage","wrong":["quarrel","compete","celebrate"]},{"contextId":"u6_08_engage_gap_3","answer":"engage","wrong":["compare","bargain","trade"]}],"spellingErrors":["enguage","engege","engaje","ingage","engadge","engaige"],"wordFamilyForms":[{"form":"engage","partOfSpeech":"verb","example":"Good teachers find ways to engage every student in the lesson.","pedagogicallyUseful":true},{"form":"engagement","partOfSpeech":"noun","example":"Student engagement rises when lessons connect to real life.","pedagogicallyUseful":true,"altExample":"Teachers measure engagement by how many students ask questions during a lesson."},{"form":"engaging","partOfSpeech":"adjective","example":"The speaker gave an engaging talk that held the attention of the whole hall.","pedagogicallyUseful":true,"altExample":"Short videos can make a difficult topic more engaging for younger learners."}],"masteryPassages":[{"passageId":"u6_08_engage_passage_1","contextId":"u6_08_engage_gap_1","text":"Some students sit quietly through every lesson and only listen. A good teacher tries to make learning active, so that pupils ____ with the topic instead of just taking notes.","answer":"engage"},{"passageId":"u6_08_engage_passage_2","contextId":"u6_08_engage_gap_2","text":"Online courses often lose their students after the first week. Learners are far more likely to carry on if the lessons give them real tasks to ____ in, such as writing a short report or recording a talk.","answer":"engage"}],"contextDependentParaphrases":[],"wrongParaphrases":["become embarrassed","become exhausted","become confused"],"misleadingDistractors":["to leave a lesson before it finishes","to watch a lesson without joining in","to prepare a lesson for other people"],"teacherNote":"Taught in the learning sense: to become involved and interested in an activity (engage with a topic, engage in a discussion). The senses “to hire someone” and “to become engaged to marry” are not taught."}]'::jsonb,'["engagement","engaging"]'::jsonb,'["engage with a topic","engage in discussion","actively engage"]'::jsonb,'live'),
('vocab_participate','participate','verb','to take part in an activity','[{"senseId":"participate_1","meaning":"to take part in an activity","acceptedParaphrases":["take part","join in"],"masteryContexts":[{"contextId":"u6_09_participate_meaning","text":"Pupils who participate in class discussions usually understand the topic better than those who stay silent.","meaning":"to take part in an activity","wrongMeanings":["to lead an activity from the front","to watch an activity quietly","to plan an activity in advance"]},{"contextId":"u6_09_participate_paraphrase","text":"Over two hundred students from five schools will participate in the science competition next month.","meaning":"to take part in an event","wrongMeanings":["to organise an event for others","to report on an event afterwards","to win a prize at an event"]}],"situationDistractors":["The students sat in rows and listened to the speaker without asking questions.","The coach sat in the stands and watched the match through binoculars.","The headteacher cancelled the match because heavy snow covered the field.","A visitor handed the receptionist a letter and waited in the entrance hall.","The teacher collected the textbooks and counted them before locking the cupboard.","The school secretary typed the timetable and printed it for every classroom."],"gapDistractors":[{"contextId":"u6_09_participate_gap_1","answer":"participate","wrong":["invest","succeed","result"]},{"contextId":"u6_09_participate_gap_2","answer":"participate","wrong":["result","invest","believe"]},{"contextId":"u6_09_participate_gap_3","answer":"participate","wrong":["succeed","consist","insist"]}],"spellingErrors":["particpate","partisipate","participat","partcipate","participete","particapate"],"wordFamilyForms":[{"form":"participate","partOfSpeech":"verb","example":"Every student is encouraged to participate in the class debate.","pedagogicallyUseful":true},{"form":"participation","partOfSpeech":"noun","example":"Active participation in lessons improves both understanding and memory.","pedagogicallyUseful":true,"altExample":"Class participation counts for ten per cent of the final grade."},{"form":"participant","partOfSpeech":"noun","example":"Each participant received a certificate at the end of the workshop.","pedagogicallyUseful":true,"altExample":"One participant in the survey said that group work had improved her speaking."}],"masteryPassages":[{"passageId":"u6_09_participate_passage_1","contextId":"u6_09_participate_gap_1","text":"In the old lessons, the teacher spoke for forty minutes and the students listened. Now every pupil is expected to ____ by asking questions, sharing ideas or helping to solve a problem on the board.","answer":"participate"},{"passageId":"u6_09_participate_passage_2","contextId":"u6_09_participate_gap_2","text":"The school choir is open to everyone, whether they have a strong voice or not. Anyone who wants to ____ only has to come to the music room on Tuesday after lessons.","answer":"participate"}],"contextDependentParaphrases":[],"wrongParaphrases":["stand apart","look on","stay behind"],"misleadingDistractors":["to watch an activity from a distance","to organise an activity for other people","to avoid an activity that is difficult"],"teacherNote":"Participate is the more formal verb for take part; it is followed by “in” (participate in a discussion). Participant (a person who takes part) is a separate target in Units 3 and 4."}]'::jsonb,'["participation","participant"]'::jsonb,'["participate in a discussion","actively participate","participate in an event"]'::jsonb,'live'),
('vocab_passive','passive','adjective','not actively involved; receiving or accepting rather than contributing or taking action','[{"senseId":"passive_1","meaning":"not actively involved; receiving or accepting rather than contributing or taking action","acceptedParaphrases":["not actively involved","taking no active part"],"masteryContexts":[{"contextId":"u6_10_passive_meaning","text":"Reading the same notes silently is a passive way of studying, because you never ask yourself any questions.","meaning":"receiving information without taking action to use it","wrongMeanings":["calm and quiet while studying","lazy and unwilling to study","slow but careful when studying"]},{"contextId":"u6_10_passive_paraphrase","text":"Lectures can be passive experiences unless students are given tasks to do and questions to answer.","meaning":"not actively involved","wrongMeanings":["too tired to listen carefully","too nervous to join in at all","too lazy to attend lectures"]}],"situationDistractors":["The students split into groups, planned a short play and performed it for the class.","The teacher asked the class to design a poster, and every pupil added something.","The pupil put up his hand twice to ask a question and then explained his idea to the group.","The librarian recommended a book about volcanoes to a curious first-year student.","The exam hall was silent, and every pupil wrote for the whole two hours.","The teacher stood at the door and welcomed each pupil by name."],"gapDistractors":[{"contextId":"u6_10_passive_gap_1","answer":"passive","wrong":["expensive","noisy","private"]},{"contextId":"u6_10_passive_gap_2","answer":"passive","wrong":["noisy","generous","impatient"]},{"contextId":"u6_10_passive_gap_3","answer":"passive","wrong":["generous","noisy","tidy"]}],"spellingErrors":["pasive","passiv","passsive","passeve","pessive","pasiv"],"masteryPassages":[{"passageId":"u6_10_passive_passage_1","contextId":"u6_10_passive_gap_1","text":"Some students believe that studying means reading the same pages again and again. This is a ____ method, because the brain only receives information and never has to use it, whereas writing questions or testing yourself works much better.","answer":"passive"},{"passageId":"u6_10_passive_passage_2","contextId":"u6_10_passive_gap_2","text":"During the group project, two members stayed ____ and left all the research and writing to the others, even though everybody had agreed to share the work. The teacher later asked them to describe what they had contributed, and neither could give an answer.","answer":"passive"}],"contextDependentParaphrases":[],"wrongParaphrases":["calm in every situation","lazy and unwilling to work","too shy to speak aloud"],"misleadingDistractors":["calm and relaxed in difficult situations","lazy and unwilling to attend lessons","shy and unable to speak in public"],"teacherNote":"Passive describes someone who receives or accepts without taking action or contributing. It is not the same as calm, quiet or lazy: a quiet student can be very actively involved."}]'::jsonb,'[]'::jsonb,'["passive learner","passive way of learning","remain passive"]'::jsonb,'live')
