values
('u6_01_absorb_meaning','vocab_absorb','u6_01_absorb','absorb_1','meaning_context','Young children absorb new vocabulary quickly when they hear it used in everyday conversation.',null,'["take in and understand"]'::jsonb,null,'live'),
('u6_01_absorb_paraphrase','vocab_absorb','u6_01_absorb','absorb_1','paraphrase_context','Young children take in and understand new vocabulary quickly when they hear it used in everyday conversation.','take in and understand','["absorb"]'::jsonb,null,'live'),
('u6_01_absorb_production','vocab_absorb','u6_01_absorb','absorb_1','production_context','It is difficult to learn and take in a long list of facts if you read it only once.','learn and take in','["absorb"]'::jsonb,null,'live'),
('u6_01_absorb_gap_1','vocab_absorb','u6_01_absorb','absorb_1','gap_fill','Good teachers give students short sections of text so that they can absorb the main ideas before moving on.','absorb','["absorb"]'::jsonb,null,'live'),
('u6_01_absorb_gap_2','vocab_absorb','u6_01_absorb','absorb_1','gap_fill','It is much easier to absorb new information when you are rested and not worried about other things.','absorb','["absorb"]'::jsonb,null,'live'),
('u6_01_absorb_gap_3','vocab_absorb','u6_01_absorb','absorb_1','gap_fill','The teacher played the recording twice so that the class could absorb every detail of the conversation.','absorb','["absorb"]'::jsonb,null,'live'),
('u6_02_confidence_meaning','vocab_confidence','u6_02_confidence','confidence_1','meaning_context','Speaking in front of the class is hard at first, but regular practice builds confidence over time.',null,'["belief in yourself"]'::jsonb,null,'live'),
('u6_02_confidence_paraphrase','vocab_confidence','u6_02_confidence','confidence_1','paraphrase_context','Speaking in front of the class is hard at first, but regular practice builds belief in yourself over time.','belief in yourself','["confidence"]'::jsonb,null,'live'),
('u6_02_confidence_production','vocab_confidence','u6_02_confidence','confidence_1','production_context','If you practise every day, you will soon have more trust in your own ability.','trust in your own ability','["confidence"]'::jsonb,null,'live'),
('u6_02_confidence_gap_1','vocab_confidence','u6_02_confidence','confidence_1','gap_fill','Learners who prepare carefully for speaking tests usually perform with more confidence on the day.','confidence','["confidence"]'::jsonb,null,'live'),
('u6_02_confidence_gap_2','vocab_confidence','u6_02_confidence','confidence_1','gap_fill','Her confidence grew as she realised that she could follow the whole lecture without any help.','confidence','["confidence"]'::jsonb,null,'live'),
('u6_02_confidence_gap_3','vocab_confidence','u6_02_confidence','confidence_1','gap_fill','A good teacher corrects mistakes kindly so that students do not lose confidence in their own ability.','confidence','["confidence"]'::jsonb,null,'live'),
('u6_03_dilemma_meaning','vocab_dilemma','u6_03_dilemma','dilemma_1','meaning_context','Many students face a dilemma when they have to choose between a part-time job and extra study time.',null,'["difficult choice"]'::jsonb,null,'live'),
('u6_03_dilemma_paraphrase','vocab_dilemma','u6_03_dilemma','dilemma_1','paraphrase_context','Many students face a difficult choice when they have to choose between a part-time job and extra study time.','difficult choice','["dilemma"]'::jsonb,null,'live'),
('u6_03_dilemma_production','vocab_dilemma','u6_03_dilemma','dilemma_1','production_context','Deciding which subjects to drop at the end of the year is a hard decision for many students.','hard decision','["dilemma"]'::jsonb,null,'live'),
('u6_03_dilemma_gap_1','vocab_dilemma','u6_03_dilemma','dilemma_1','gap_fill','Teenagers often face the dilemma of choosing between more study time and an active social life.','dilemma','["dilemma"]'::jsonb,null,'live'),
('u6_03_dilemma_gap_2','vocab_dilemma','u6_03_dilemma','dilemma_1','gap_fill','The manager described it as a real dilemma, since any choice would upset one of the two teams.','dilemma','["dilemma"]'::jsonb,null,'live'),
('u6_03_dilemma_gap_3','vocab_dilemma','u6_03_dilemma','dilemma_1','gap_fill','Whether to tell the teacher about the mistake or to keep quiet was a dilemma that kept him awake all night.','dilemma','["dilemma"]'::jsonb,null,'live'),
('u6_04_dramatically_meaning','vocab_dramatically','u6_04_dramatically','dramatically_1','meaning_context','Exam results improved dramatically after the school introduced weekly revision lessons.',null,'["to a very great extent"]'::jsonb,null,'live'),
('u6_04_dramatically_paraphrase','vocab_dramatically','u6_04_dramatically','dramatically_1','paraphrase_context','Exam results improved to a very great extent after the school introduced weekly revision lessons.','to a very great extent','["dramatically"]'::jsonb,null,'live'),
('u6_04_dramatically_production','vocab_dramatically','u6_04_dramatically','dramatically_1','production_context','Attendance rose in a very noticeable way once the lessons started at a later time.','in a very noticeable way','["dramatically"]'::jsonb,null,'live'),
('u6_04_dramatically_gap_1','vocab_dramatically','u6_04_dramatically','dramatically_1','gap_fill','The number of students using online dictionaries has increased dramatically over the past ten years, from fewer than a hundred to several thousand.','dramatically','["dramatically"]'::jsonb,null,'live'),
('u6_04_dramatically_gap_2','vocab_dramatically','u6_04_dramatically','dramatically_1','gap_fill','Her attitude to homework changed dramatically when she realised how much it improved her results, and she went from avoiding it to starting it on the day it was set.','dramatically','["dramatically"]'::jsonb,null,'live'),
('u6_04_dramatically_gap_3','vocab_dramatically','u6_04_dramatically','dramatically_1','gap_fill','Test scores fell dramatically in the school where lessons were halved in length, dropping by almost a third.','dramatically','["dramatically"]'::jsonb,null,'live'),
('u6_05_equivalent_meaning','vocab_equivalent','u6_05_equivalent','equivalent_1','meaning_context','A grade B in this examination is equivalent to a grade 6 in the national system.',null,'["equal in value"]'::jsonb,null,'live'),
('u6_05_equivalent_paraphrase','vocab_equivalent','u6_05_equivalent','equivalent_1','paraphrase_context','A grade B in this examination is equal in value to a grade 6 in the national system.','equal in value','["equivalent"]'::jsonb,null,'live'),
('u6_05_equivalent_production','vocab_equivalent','u6_05_equivalent','equivalent_1','production_context','For basic note-taking, a tablet is equal in function to a laptop.','equal in function','["equivalent"]'::jsonb,null,'live'),
('u6_05_equivalent_gap_1','vocab_equivalent','u6_05_equivalent','equivalent_1','gap_fill','In many countries, a vocational diploma is considered equivalent to the first year of a degree course, so successful students can enter the second year directly.','equivalent','["equivalent"]'::jsonb,null,'live'),
('u6_05_equivalent_gap_2','vocab_equivalent','u6_05_equivalent','equivalent_1','gap_fill','The exam board explained that the two papers were equivalent in difficulty, so no group of students had an unfair advantage.','equivalent','["equivalent"]'::jsonb,null,'live'),
('u6_05_equivalent_gap_3','vocab_equivalent','u6_05_equivalent','equivalent_1','gap_fill','A score of 7.0 on this test is roughly equivalent to the level of an educated native speaker, according to the examiners.','equivalent','["equivalent"]'::jsonb,null,'live'),
('u6_06_overload_meaning','vocab_overload','u6_06_overload','overload_1','meaning_context','Teachers try not to overload students in the weeks before examinations.',null,'["give too much work to"]'::jsonb,null,'live'),
('u6_06_overload_paraphrase','vocab_overload','u6_06_overload','overload_1','paraphrase_context','Teachers try not to give too much work to students in the weeks before examinations.','give too much work to','["overload"]'::jsonb,null,'live'),
('u6_06_overload_production','vocab_overload','u6_06_overload','overload_1','production_context','Parents should be careful not to ask too much of children who are already tired.','ask too much of','["overload"]'::jsonb,null,'live'),
('u6_06_overload_gap_1','vocab_overload','u6_06_overload','overload_1','gap_fill','The school tries not to overload younger students with homework, because they need time to play and rest.','overload','["overload"]'::jsonb,null,'live'),
('u6_06_overload_gap_2','vocab_overload','u6_06_overload','overload_1','gap_fill','Experienced teachers know that it is a mistake to overload a single lesson with too many new words.','overload','["overload"]'::jsonb,null,'live'),
('u6_06_overload_gap_3','vocab_overload','u6_06_overload','overload_1','gap_fill','Some students overload their timetable with extra clubs and then have no energy left for their homework.','overload','["overload"]'::jsonb,null,'live'),
('u6_07_stagnate_meaning','vocab_stagnate','u6_07_stagnate','stagnate_1','meaning_context','Students who only repeat the same exercises will stagnate, because they never meet new challenges.',null,'["stop improving"]'::jsonb,null,'live'),
('u6_07_stagnate_paraphrase','vocab_stagnate','u6_07_stagnate','stagnate_1','paraphrase_context','Students who only repeat the same exercises will stop improving, because they never meet new challenges.','stop improving','["stagnate"]'::jsonb,null,'live'),
('u6_07_stagnate_production','vocab_stagnate','u6_07_stagnate','stagnate_1','production_context','Learners who avoid difficult tasks usually fail to make progress, however many hours they spend studying.','fail to make progress','["stagnate"]'::jsonb,null,'live'),
('u6_07_stagnate_gap_1','vocab_stagnate','u6_07_stagnate','stagnate_1','gap_fill','Without new challenges, even a talented pianist can stagnate and lose the desire to practise.','stagnate','["stagnate"]'::jsonb,null,'live'),
('u6_07_stagnate_gap_2','vocab_stagnate','u6_07_stagnate','stagnate_1','gap_fill','If students keep using the same revision method every time, their progress may stagnate after a few weeks.','stagnate','["stagnate"]'::jsonb,null,'live'),
('u6_07_stagnate_gap_3','vocab_stagnate','u6_07_stagnate','stagnate_1','gap_fill','The town began to stagnate when its biggest factory closed and no new businesses arrived.','stagnate','["stagnate"]'::jsonb,null,'live'),
('u6_08_engage_meaning','vocab_engage','u6_08_engage','engage_1','meaning_context','Students are more likely to engage with a text if they discuss it with a partner before writing.',null,'["become involved"]'::jsonb,null,'live'),
('u6_08_engage_paraphrase','vocab_engage','u6_08_engage','engage_1','paraphrase_context','Students are more likely to become involved with a text if they discuss it with a partner before writing.','become involved','["engage"]'::jsonb,null,'live'),
('u6_08_engage_production','vocab_engage','u6_08_engage','engage_1','production_context','Teenagers are more likely to take a real interest in lessons that connect to the world outside school.','take a real interest','["engage"]'::jsonb,null,'live'),
('u6_08_engage_gap_1','vocab_engage','u6_08_engage','engage_1','gap_fill','Pupils who engage fully in group discussions usually remember the lesson much longer than those who sit silently.','engage','["engage"]'::jsonb,null,'live'),
('u6_08_engage_gap_2','vocab_engage','u6_08_engage','engage_1','gap_fill','The best teachers find ways to help every student to engage with the material, not just the quickest learners.','engage','["engage"]'::jsonb,null,'live'),
('u6_08_engage_gap_3','vocab_engage','u6_08_engage','engage_1','gap_fill','During the workshop, parents were invited to engage with their children’s projects instead of simply looking at them.','engage','["engage"]'::jsonb,null,'live'),
('u6_09_participate_meaning','vocab_participate','u6_09_participate','participate_1','meaning_context','All students are expected to participate in at least one activity outside the classroom each week.',null,'["take part"]'::jsonb,null,'live'),
('u6_09_participate_paraphrase','vocab_participate','u6_09_participate','participate_1','paraphrase_context','All students are expected to take part in at least one activity outside the classroom each week.','take part','["participate"]'::jsonb,null,'live'),
('u6_09_participate_production','vocab_participate','u6_09_participate','participate_1','production_context','Shy students often find it easier to join in when the group is small.','join in','["participate"]'::jsonb,null,'live'),
('u6_09_participate_gap_1','vocab_participate','u6_09_participate','participate_1','gap_fill','Visitors are welcome to participate in the workshop, but they must register at the main desk first.','participate','["participate"]'::jsonb,null,'live'),
('u6_09_participate_gap_2','vocab_participate','u6_09_participate','participate_1','gap_fill','Only students who have completed the safety training are allowed to participate in the laboratory experiment.','participate','["participate"]'::jsonb,null,'live'),
('u6_09_participate_gap_3','vocab_participate','u6_09_participate','participate_1','gap_fill','In a good seminar, everyone is encouraged to participate rather than leaving the talking to one or two people.','participate','["participate"]'::jsonb,null,'live'),
('u6_10_passive_meaning','vocab_passive','u6_10_passive','passive_1','meaning_context','Students who are passive in lessons listen carefully but rarely ask questions or give opinions.',null,'["not actively involved"]'::jsonb,null,'live'),
('u6_10_passive_paraphrase','vocab_passive','u6_10_passive','passive_1','paraphrase_context','Students who are not actively involved in lessons listen carefully but rarely ask questions or give opinions.','not actively involved','["passive"]'::jsonb,null,'live'),
('u6_10_passive_production','vocab_passive','u6_10_passive','passive_1','production_context','Students who are taking no active part in a discussion usually learn very little from it.','taking no active part','["passive"]'::jsonb,null,'live'),
('u6_10_passive_gap_1','vocab_passive','u6_10_passive','passive_1','gap_fill','Watching videos without taking notes or answering questions is a very passive way to learn a language.','passive','["passive"]'::jsonb,null,'live'),
('u6_10_passive_gap_2','vocab_passive','u6_10_passive','passive_1','gap_fill','Teachers who ask open questions turn passive listeners into active thinkers.','passive','["passive"]'::jsonb,null,'live'),
('u6_10_passive_gap_3','vocab_passive','u6_10_passive','passive_1','gap_fill','A passive student waits for the teacher to give the answer, whereas an active one tries to find it first.','passive','["passive"]'::jsonb,null,'live')
