('u6_idea_absorb',6,'idea_set','{"originalIdea":"Students absorb more information when lessons are divided into short sections.","accurateParaphrases":["Students take in and understand more when a lesson is split into short parts.","Dividing a lesson into short sections helps students to learn more of what is taught.","More of the information sinks in for students if lessons come in short sections."],"meaningInvariants":[{"type":"comparison","value":"more information"}],"distractors":[{"text":"Students absorb less information when lessons are divided into short sections.","misconceptionCategory":"polarity_change"},{"text":"Students absorb the same amount of information however a lesson is divided.","misconceptionCategory":"comparison_change"},{"text":"Teachers absorb more information when lessons are divided into short sections.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_absorb"],"primaryEvidenceTargetId":"vocab_absorb"}'::jsonb,'live'),
('u6_idea_confidence',6,'idea_set','{"originalIdea":"Regular speaking practice gives learners the confidence to answer questions in class.","accurateParaphrases":["Learners who practise speaking regularly come to believe in their ability to answer questions in class.","Practising speaking often makes learners trust their own ability to reply when the teacher asks a question.","Frequent speaking practice helps learners to feel sure of themselves when they have to answer in class."],"meaningInvariants":[{"type":"cause_effect","value":"regular practice gives belief in yourself"}],"distractors":[{"text":"Regular speaking practice makes learners afraid to answer questions in class.","misconceptionCategory":"polarity_change"},{"text":"Regular speaking practice gives learners the certainty that every answer in class is correct.","misconceptionCategory":"meaning_confusion"},{"text":"Answering questions in class gives learners the opportunity to practise speaking regularly.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_confidence"],"primaryEvidenceTargetId":"vocab_confidence"}'::jsonb,'live'),
('u6_idea_dilemma',6,'idea_set','{"originalIdea":"Many students face a dilemma when they must choose between a part-time job and extra study time.","accurateParaphrases":["Many students find it hard to decide between earning money from a part-time job and spending more time studying.","Choosing between working part-time and studying for longer is a difficult decision for many students.","A lot of students struggle to choose between a part-time job and additional time for their studies."],"meaningInvariants":[{"type":"quantity","value":"many students"}],"distractors":[{"text":"Few students face a dilemma when they must choose between a part-time job and extra study time.","misconceptionCategory":"quantity_change"},{"text":"Many students face no difficulty when they must choose between a part-time job and extra study time.","misconceptionCategory":"polarity_change"},{"text":"Many students face a dilemma when they must choose between two part-time jobs.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_dilemma"],"primaryEvidenceTargetId":"vocab_dilemma"}'::jsonb,'live'),
('u6_idea_dramatically',6,'idea_set','{"originalIdea":"The number of students who study online has risen dramatically since 2015.","accurateParaphrases":["Since 2015 there has been a very large increase in the number of students who study online.","The number of students studying online has grown by a very large amount since 2015.","Far more students study online now than in 2015, and the rise has been very steep."],"meaningInvariants":[{"type":"degree","value":"very large"}],"distractors":[{"text":"The number of students who study online has risen slightly since 2015.","misconceptionCategory":"degree_change"},{"text":"The number of students who study online has fallen dramatically since 2015.","misconceptionCategory":"polarity_change"},{"text":"The number of students who study online has risen dramatically since 2005.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_dramatically"],"primaryEvidenceTargetId":"vocab_dramatically"}'::jsonb,'live'),
('u6_idea_equivalent',6,'idea_set','{"originalIdea":"This foreign diploma is equivalent to the national school certificate.","accurateParaphrases":["This foreign diploma has the same value as the national school certificate.","The national school certificate and this foreign diploma are worth the same.","This foreign diploma counts as equal to the national school certificate."],"meaningInvariants":[{"type":"comparison","value":"the same value"}],"distractors":[{"text":"This foreign diploma is better than the national school certificate.","misconceptionCategory":"comparison_change"},{"text":"This foreign diploma is similar in appearance to the national school certificate.","misconceptionCategory":"meaning_confusion"},{"text":"This foreign diploma cannot be accepted instead of the national school certificate.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_equivalent"],"primaryEvidenceTargetId":"vocab_equivalent"}'::jsonb,'live'),
('u6_idea_overload',6,'idea_set','{"originalIdea":"Teachers should not overload students with homework before examinations.","accurateParaphrases":["Teachers should avoid giving students more homework than they can manage before examinations.","Before examinations, students should not be given too much homework by their teachers.","Teachers should not burden students with excessive homework in the run-up to examinations."],"meaningInvariants":[{"type":"degree","value":"more than they can manage"}],"distractors":[{"text":"Teachers should give students more homework before examinations.","misconceptionCategory":"polarity_change"},{"text":"Teachers should not give students any homework at all after examinations.","misconceptionCategory":"time_change"},{"text":"Students should not overload teachers with questions before examinations.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_overload"],"primaryEvidenceTargetId":"vocab_overload"}'::jsonb,'live'),
('u6_idea_stagnate',6,'idea_set','{"originalIdea":"The school’s results stagnated for five years before the new teaching methods were introduced.","accurateParaphrases":["For five years the school’s results made no progress until new teaching methods arrived.","Until the new teaching methods were introduced, the school’s results stayed at the same level for five years.","The school’s results stopped improving for five years until the new teaching methods were introduced."],"meaningInvariants":[{"type":"time","value":"five years before"}],"distractors":[{"text":"The school’s results stagnated for five years after the new teaching methods were introduced.","misconceptionCategory":"time_change"},{"text":"The school’s results improved quickly for five years before the new teaching methods were introduced.","misconceptionCategory":"polarity_change"},{"text":"The school’s results stagnated for ten years before the new teaching methods were introduced.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_stagnate"],"primaryEvidenceTargetId":"vocab_stagnate"}'::jsonb,'live'),
('u6_idea_engage',6,'idea_set','{"originalIdea":"Students engage more with lessons that connect to their own lives.","accurateParaphrases":["Students become more involved in lessons that connect to their own lives.","Students take a greater interest in lessons that are linked to their own lives.","Lessons that relate to their own lives hold the interest of students more strongly."],"meaningInvariants":[{"type":"comparison","value":"more"}],"distractors":[{"text":"Students engage less with lessons that connect to their own lives.","misconceptionCategory":"polarity_change"},{"text":"Students engage more with lessons that connect to their teachers’ lives.","misconceptionCategory":"meaning_confusion"},{"text":"Students engage more with lessons that are shorter than usual.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_engage"],"primaryEvidenceTargetId":"vocab_engage"}'::jsonb,'live'),
('u6_idea_participate',6,'idea_set','{"originalIdea":"Students who participate in sport tend to perform better in their studies.","accurateParaphrases":["Students who take part in sport usually do better in their schoolwork.","Those who join in sporting activities generally achieve better results in their studies.","Taking part in sport is linked with stronger performance in studies."],"meaningInvariants":[{"type":"comparison","value":"perform better"}],"distractors":[{"text":"Students who participate in sport perform worse in their studies.","misconceptionCategory":"polarity_change"},{"text":"Students who watch sport tend to perform better in their studies.","misconceptionCategory":"meaning_confusion"},{"text":"All students who participate in sport perform better in their studies.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_participate"],"primaryEvidenceTargetId":"vocab_participate"}'::jsonb,'live'),
('u6_idea_passive',6,'idea_set','{"originalIdea":"Passive learning rarely helps students to remember new vocabulary.","accurateParaphrases":["Learning in which students only receive information rarely helps them to remember new words.","Students seldom remember new vocabulary when they simply receive it without taking action.","It is unusual for students to remember new words if they are not actively involved in learning."],"meaningInvariants":[{"type":"degree","value":"rarely"}],"distractors":[{"text":"Passive learning always helps students to remember new vocabulary.","misconceptionCategory":"polarity_change"},{"text":"Passive learning rarely helps students to remember new grammar.","misconceptionCategory":"meaning_confusion"},{"text":"Passive learning sometimes helps students to forget new vocabulary.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_passive"],"primaryEvidenceTargetId":"vocab_passive"}'::jsonb,'live'),
('u6_idea_active',6,'idea_set','{"originalIdea":"Students who are active in lessons usually remember more than students who only listen.","accurateParaphrases":["Students who take a full part in lessons generally remember more than those who simply listen.","Learners who are fully involved in class tend to recall more than learners who just listen.","Taking a real part in lessons helps students to remember more than listening alone does."],"meaningInvariants":[{"type":"comparison","value":"remember more"}],"distractors":[{"text":"Students who are active in lessons usually remember less than students who only listen.","misconceptionCategory":"polarity_change"},{"text":"Students who are physically energetic in lessons usually remember more than students who only listen.","misconceptionCategory":"meaning_confusion"},{"text":"Students who are active in lessons always remember more than students who only listen.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_active"],"primaryEvidenceTargetId":"vocab_active"}'::jsonb,'live'),
('u6_idea_evaluate',6,'idea_set','{"originalIdea":"Teachers should evaluate each new method by comparing students’ results before and after it is introduced.","accurateParaphrases":["Teachers should judge how well each new method works by comparing students’ results from before and after its introduction.","Each new method should be judged by comparing the results that students achieved before it began with those they achieved afterwards.","Teachers ought to measure the success of every new method by looking at results from before and after it starts."],"meaningInvariants":[{"type":"comparison","value":"before and after"}],"distractors":[{"text":"Teachers should evaluate each new method.","misconceptionCategory":"omitted_information"},{"text":"Teachers should describe each new method by comparing students’ results before and after it is introduced.","misconceptionCategory":"meaning_confusion"},{"text":"Teachers should evaluate each new method by comparing students’ results only after it is introduced.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_evaluate_6"],"primaryEvidenceTargetId":"vocab_evaluate_6"}'::jsonb,'live'),
('u6_idea_reflect',6,'idea_set','{"originalIdea":"Athletes who reflect on their mistakes after a match usually improve faster than those who ignore them.","accurateParaphrases":["Athletes who think carefully about their mistakes once a match is over generally improve more quickly than those who pay them no attention.","After a match, athletes who look back on what went wrong tend to get better faster than those who disregard it.","Improvement comes sooner for athletes who consider their errors after a game than for those who take no notice of them."],"meaningInvariants":[{"type":"comparison","value":"improve faster"}],"distractors":[{"text":"Athletes who reflect on their mistakes after a match usually improve more slowly than those who ignore them.","misconceptionCategory":"polarity_change"},{"text":"Athletes who reflect on their mistakes before a match usually improve faster than those who ignore them.","misconceptionCategory":"time_change"},{"text":"Athletes who reflect on their mistakes after a match always improve faster than those who ignore them.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_reflect"],"primaryEvidenceTargetId":"vocab_reflect"}'::jsonb,'live'),
('u6_idea_process',6,'idea_set','{"originalIdea":"The brain can process only a limited amount of new information at one time, so very long lectures are rarely helpful.","accurateParaphrases":["Because the brain can take in and understand only a small amount of new information at once, very long lectures are rarely helpful.","Very long lectures seldom help, since the brain can make sense of only a limited amount of new information at a time.","The amount of new information that the brain can understand at one moment is limited, so lengthy lectures are seldom useful."],"meaningInvariants":[{"type":"cause_effect","value":"limited capacity, so long lectures rarely help"}],"distractors":[{"text":"The brain can process only a limited amount of new information at one time because very long lectures are rarely helpful.","misconceptionCategory":"cause_effect_change"},{"text":"The brain can process a very large amount of new information at one time, so very long lectures are often helpful.","misconceptionCategory":"quantity_change"},{"text":"Very long lectures are rarely helpful.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_process"],"primaryEvidenceTargetId":"vocab_process"}'::jsonb,'live'),
('u6_idea_strategy',6,'idea_set','{"originalIdea":"Successful learners usually have a strategy that combines short study sessions with regular self-testing.","accurateParaphrases":["Learners who do well generally follow a planned method that mixes short periods of study with frequent self-testing.","Most successful learners have a clear plan for reaching their goals that includes brief study sessions and regular self-testing.","A carefully planned method of short study sessions and regular self-testing is typical of successful learners."],"meaningInvariants":[{"type":"quantity","value":"short sessions and regular self-testing"}],"distractors":[{"text":"Successful learners usually have a strategy that combines long study sessions with regular self-testing.","misconceptionCategory":"degree_change"},{"text":"Successful learners rarely have a strategy that combines short study sessions with regular self-testing.","misconceptionCategory":"polarity_change"},{"text":"Successful learners usually have a strategy that combines short study sessions.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_strategy"],"primaryEvidenceTargetId":"vocab_strategy"}'::jsonb,'live'),
('u6_idea_approach',6,'idea_set','{"originalIdea":"The school has adopted a new approach to behaviour, which rewards good conduct instead of punishing poor conduct.","accurateParaphrases":["The school has introduced a different way of dealing with behaviour, in which good conduct is rewarded rather than poor conduct punished.","Instead of punishing bad conduct, the school now has a different method for behaviour that gives rewards for good conduct.","The school has switched to a new way of handling behaviour: it praises and rewards good conduct and no longer relies on punishment."],"meaningInvariants":[{"type":"polarity","value":"rewards good conduct instead of punishing poor conduct"}],"distractors":[{"text":"The school has adopted a new approach to behaviour, which punishes poor conduct instead of rewarding good conduct.","misconceptionCategory":"polarity_change"},{"text":"The school has adopted a new approach to behaviour.","misconceptionCategory":"omitted_information"},{"text":"The school has adopted a new rule about behaviour, which rewards good conduct instead of punishing poor conduct.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_approach"],"primaryEvidenceTargetId":"vocab_approach"}'::jsonb,'live'),
('u6_idea_revise',6,'idea_set','{"originalIdea":"Students who revise a little every day usually feel calmer before a test than students who leave everything until the last night.","accurateParaphrases":["Students who go back over their work a little each day generally feel calmer before a test than those who put it all off until the final night.","Studying material again in small amounts every day tends to leave students calmer before a test than waiting until the last night does.","Those who prepare by studying for a short time each day usually feel less worried about a test than those who wait until the night before."],"meaningInvariants":[{"type":"comparison","value":"calmer"}],"distractors":[{"text":"Students who revise a little every day usually feel more nervous before a test than students who leave everything until the last night.","misconceptionCategory":"polarity_change"},{"text":"Students who revise a little every day feel exactly as calm before a test as students who leave everything until the last night.","misconceptionCategory":"comparison_change"},{"text":"Students who revise for many hours every day usually feel calmer before a test than students who leave everything until the last night.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_revise"],"primaryEvidenceTargetId":"vocab_revise"}'::jsonb,'live'),
('u6_idea_forecast',6,'idea_set','{"originalIdea":"Economists forecast that house prices will fall slightly next year because interest rates are rising.","accurateParaphrases":["Economists expect, on the basis of current figures, a slight drop in house prices next year because interest rates are rising.","Because interest rates are rising, economists say that house prices are likely to fall a little next year.","Next year house prices will probably fall slightly, economists say, as a result of rising interest rates."],"meaningInvariants":[{"type":"degree","value":"slightly"}],"distractors":[{"text":"Economists forecast that house prices will rise slightly next year because interest rates are rising.","misconceptionCategory":"polarity_change"},{"text":"Economists forecast that house prices will fall sharply next year because interest rates are rising.","misconceptionCategory":"degree_change"},{"text":"Economists forecast that house prices will fall slightly next year and that, as a result, interest rates are rising.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_forecast"],"primaryEvidenceTargetId":"vocab_forecast"}'::jsonb,'live'),
('u6_idea_interfere',6,'idea_set','{"originalIdea":"Working late every night can interfere with a teenager’s sleep and concentration.","accurateParaphrases":["Working until late every night can get in the way of a teenager’s sleep and ability to pay attention.","If teenagers work late every night, their sleep and their ability to concentrate may suffer.","Late work every night can harm both the sleep and the attention span of a teenager."],"meaningInvariants":[{"type":"cause_effect","value":"late work harms sleep and attention"}],"distractors":[{"text":"A lack of sleep and concentration can make a teenager work late every night.","misconceptionCategory":"cause_effect_change"},{"text":"Working late every night can improve a teenager’s sleep and concentration.","misconceptionCategory":"polarity_change"},{"text":"Working late once a month can interfere with a teenager’s sleep and concentration.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_interfere"],"primaryEvidenceTargetId":"vocab_interfere"}'::jsonb,'live'),
('u6_idea_distract',6,'idea_set','{"originalIdea":"Notifications from a mobile phone can distract students from their work for several minutes at a time.","accurateParaphrases":["Messages that appear on a mobile phone can pull students’ attention away from their work for several minutes at a time.","A phone alert can draw students’ attention away from their work, sometimes for several minutes.","For several minutes at a time, alerts from a mobile phone can take students’ attention off what they are supposed to be doing."],"meaningInvariants":[{"type":"time","value":"several minutes"}],"distractors":[{"text":"Notifications from a mobile phone can distract students from their work for a few seconds at a time.","misconceptionCategory":"time_change"},{"text":"Notifications from a mobile phone can help students to concentrate on their work for several minutes at a time.","misconceptionCategory":"polarity_change"},{"text":"Notifications from a mobile phone can distract students.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_distract"],"primaryEvidenceTargetId":"vocab_distract"}'::jsonb,'live'),
('u6_idea_evidence',6,'idea_set','{"originalIdea":"Researchers have found strong evidence that students who sleep eight hours remember more than students who sleep five.","accurateParaphrases":["Research gives solid support for the idea that students who sleep eight hours remember more than those who sleep five.","Studies strongly suggest that eight hours of sleep helps students to remember more than five hours does.","There is firm support in research for the view that students sleeping eight hours recall more than students sleeping five."],"meaningInvariants":[{"type":"comparison","value":"remember more"}],"distractors":[{"text":"Researchers have found strong evidence that students who sleep eight hours remember less than students who sleep five.","misconceptionCategory":"polarity_change"},{"text":"Researchers have proved beyond doubt that students who sleep eight hours remember more than students who sleep five.","misconceptionCategory":"degree_change"},{"text":"Researchers have found strong evidence that students who sleep eight hours remember more than students who sleep seven.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_evidence"],"primaryEvidenceTargetId":"vocab_evidence"}'::jsonb,'live'),
('u6_idea_guidance',6,'idea_set','{"originalIdea":"Teachers should offer guidance rather than orders, so that students still make their own decisions.","accurateParaphrases":["Teachers ought to give helpful advice instead of commands, leaving the decisions to the students.","Instead of telling students what to do, teachers should advise them and let them decide.","Students should be helped by their teachers to choose for themselves, not instructed what to choose."],"meaningInvariants":[{"type":"polarity","value":"advice rather than orders"}],"distractors":[{"text":"Teachers should give orders rather than guidance, so that students do not make their own decisions.","misconceptionCategory":"polarity_change"},{"text":"Teachers should offer guidance.","misconceptionCategory":"omitted_information"},{"text":"Teachers should offer rewards rather than orders, so that students still make their own decisions.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_guidance"],"primaryEvidenceTargetId":"vocab_guidance"}'::jsonb,'live'),
('u6_idea_academic',6,'idea_set','{"originalIdea":"Schools in the region are judged mainly on academic achievement, while sport and music receive less attention.","accurateParaphrases":["The region’s schools are assessed chiefly on how well students do in their studies, and sport and music matter less.","Success in study is the main measure of the region’s schools, with less weight given to sport and music.","Sport and music are given less attention than study results when schools in the region are assessed."],"meaningInvariants":[{"type":"comparison","value":"mainly study results, less sport and music"}],"distractors":[{"text":"Schools in the region are judged mainly on sport and music, while academic achievement receives less attention.","misconceptionCategory":"comparison_change"},{"text":"Schools in the region are judged partly on academic achievement, and sport and music receive equal attention.","misconceptionCategory":"degree_change"},{"text":"Schools in the region are judged on academic achievement.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_academic"],"primaryEvidenceTargetId":"vocab_academic"}'::jsonb,'live'),
('u6_idea_concentration',6,'idea_set','{"originalIdea":"Short breaks every forty minutes can restore a student’s concentration, which usually falls during long lessons.","accurateParaphrases":["Taking a rest every forty minutes can bring back a student’s ability to pay full attention, which normally drops in long lessons.","In long lessons, a student’s attention normally declines, but a short pause every forty minutes can renew it.","A brief rest after each forty minutes of work helps students to give full attention again once it has weakened."],"meaningInvariants":[{"type":"time","value":"every forty minutes"}],"distractors":[{"text":"Short breaks every ten minutes can restore a student’s concentration, which usually falls during long lessons.","misconceptionCategory":"time_change"},{"text":"Short breaks every forty minutes can damage a student’s concentration, which usually rises during long lessons.","misconceptionCategory":"polarity_change"},{"text":"A drop in concentration during long lessons can cause students to take short breaks every forty minutes.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_concentration"],"primaryEvidenceTargetId":"vocab_concentration"}'::jsonb,'live'),
('u6_idea_complex',6,'idea_set','{"originalIdea":"Many scientists believe that the causes of the disease are complex, so no single treatment will cure it.","accurateParaphrases":["Many scientists think the disease has many connected causes that are hard to untangle, so no one treatment will cure it.","Because the causes of the disease are many and linked, many scientists expect that no single treatment will cure it.","A number of scientists say the disease has interlinked causes that are difficult to understand, so a cure will not come from one treatment."],"meaningInvariants":[{"type":"cause_effect","value":"many connected causes, so no single cure"}],"distractors":[{"text":"Many scientists believe that no single treatment will cure the disease, so its causes are complex.","misconceptionCategory":"cause_effect_change"},{"text":"A few scientists believe that the causes of the disease are complex, so no single treatment will cure it.","misconceptionCategory":"quantity_change"},{"text":"Many scientists believe that the causes of the disease are simple, so a single treatment will cure it.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_complex"],"primaryEvidenceTargetId":"vocab_complex"}'::jsonb,'live'),
('u6_idea_motivation',6,'idea_set','{"originalIdea":"Students who set their own goals usually have more motivation than students who are simply told what to do.","accurateParaphrases":["Students who choose their own targets generally feel a stronger desire to work than those who are just given instructions.","Having their own goals gives students more reason to keep working than being told what to do does.","Learners are more driven when they decide their own aims than when others simply tell them what to do."],"meaningInvariants":[{"type":"comparison","value":"more motivation"}],"distractors":[{"text":"Students who set their own goals usually have less motivation than students who are simply told what to do.","misconceptionCategory":"polarity_change"},{"text":"Students who set their own goals usually have more concentration than students who are simply told what to do.","misconceptionCategory":"meaning_confusion"},{"text":"Students who have more motivation usually set their own goals instead of being told what to do.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_motivation"],"primaryEvidenceTargetId":"vocab_motivation"}'::jsonb,'live'),
('u6_idea_curiosity',6,'idea_set','{"originalIdea":"A young scientist’s curiosity about volcanoes led her to spend three summers studying them.","accurateParaphrases":["A young scientist’s strong wish to understand volcanoes led her to study them for three summers.","Because she was so eager to learn about volcanoes, a young scientist spent three summers studying them.","Three summers of study into volcanoes resulted from a young scientist’s eager interest in them."],"meaningInvariants":[{"type":"time","value":"three summers"}],"distractors":[{"text":"A young scientist’s curiosity about volcanoes led her to spend one summer studying them.","misconceptionCategory":"quantity_change"},{"text":"Three summers of studying volcanoes led a young scientist to feel curiosity about them.","misconceptionCategory":"cause_effect_change"},{"text":"A young scientist’s fear of volcanoes led her to spend three summers studying them.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_curiosity"],"primaryEvidenceTargetId":"vocab_curiosity"}'::jsonb,'live'),
('u6_idea_technique',6,'idea_set','{"originalIdea":"A swimmer who improves her technique can swim faster without training for longer.","accurateParaphrases":["A swimmer who gets better at her skilled way of swimming can go faster without spending more time training.","By refining her method of swimming, a swimmer can increase her speed without longer training.","Faster swimming is possible through a better way of performing the strokes, with no need for extra hours of training."],"meaningInvariants":[{"type":"comparison","value":"faster without longer training"}],"distractors":[{"text":"A swimmer who improves her technique swims more slowly even though she trains for longer.","misconceptionCategory":"polarity_change"},{"text":"A swimmer who trains for longer can improve her technique without swimming faster.","misconceptionCategory":"cause_effect_change"},{"text":"A swimmer who improves her technique can swim much faster without training for longer.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_technique"],"primaryEvidenceTargetId":"vocab_technique"}'::jsonb,'live'),
('u6_idea_effective',6,'idea_set','{"originalIdea":"Experts say that regular, short lessons are more effective than a single long lesson once a week.","accurateParaphrases":["According to experts, frequent brief lessons get better results than one long weekly lesson.","Experts believe a single long weekly lesson works less well than regular short ones.","Short lessons that take place regularly achieve more, experts say, than one long lesson a week."],"meaningInvariants":[{"type":"comparison","value":"more effective"}],"distractors":[{"text":"Experts say that regular, short lessons are less effective than a single long lesson once a week.","misconceptionCategory":"polarity_change"},{"text":"Experts say that regular, short lessons are as effective as a single long lesson once a week.","misconceptionCategory":"comparison_change"},{"text":"Experts say that regular, short lessons are cheaper than a single long lesson once a week.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_effective"],"primaryEvidenceTargetId":"vocab_effective"}'::jsonb,'live'),
('u6_idea_inefficient',6,'idea_set','{"originalIdea":"The city’s old bus network is inefficient: many buses run almost empty while others are overcrowded.","accurateParaphrases":["The city’s old bus network wastes resources, since many buses are almost empty and others are packed.","Poor use is made of the old bus network in the city, with some buses nearly empty and others overcrowded.","Resources on the city’s old bus network are not well used: a number of buses carry hardly anyone while others are overfull."],"meaningInvariants":[{"type":"polarity","value":"not well used"}],"distractors":[{"text":"The city’s old bus network is well organised: buses are neither empty nor overcrowded.","misconceptionCategory":"polarity_change"},{"text":"The city’s old bus network is inefficient.","misconceptionCategory":"omitted_information"},{"text":"The city’s old bus network is unsafe: many buses run almost empty while others are overcrowded.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_inefficient"],"primaryEvidenceTargetId":"vocab_inefficient"}'::jsonb,'live'),
('u6_idea_struggle',6,'idea_set','{"originalIdea":"Many adults struggle to learn a new language because they have little time to practise.","accurateParaphrases":["Many adults find it hard to pick up a new language, since they rarely have time to practise.","Little time for practice makes learning a new language difficult for many adults.","A lack of practice time means numerous grown-ups have difficulty learning another language."],"meaningInvariants":[{"type":"cause_effect","value":"little practice time causes difficulty"}],"distractors":[{"text":"Many adults learn a new language easily because they have a lot of time to practise.","misconceptionCategory":"polarity_change"},{"text":"Many adults struggle to learn a new language.","misconceptionCategory":"omitted_information"},{"text":"Many adults struggle to learn a new language because they are afraid of making mistakes.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_struggle_6"],"primaryEvidenceTargetId":"vocab_struggle_6"}'::jsonb,'live'),
('u6_idea_awareness',6,'idea_set','{"originalIdea":"Awareness of road safety has increased sharply since the campaign began, especially among young drivers.","accurateParaphrases":["Since the campaign started, young drivers in particular have become much more conscious of road safety.","Knowledge of road safety has risen greatly since the campaign began, most of all among young drivers.","The campaign has led to a big rise in understanding of road safety, particularly for young drivers."],"meaningInvariants":[{"type":"degree","value":"sharp increase"}],"distractors":[{"text":"Awareness of road safety has fallen sharply since the campaign began, especially among young drivers.","misconceptionCategory":"polarity_change"},{"text":"Awareness of road safety has increased slightly since the campaign began, especially among young drivers.","misconceptionCategory":"degree_change"},{"text":"Awareness of road safety has increased.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_awareness"],"primaryEvidenceTargetId":"vocab_awareness"}'::jsonb,'live'),
('u6_idea_capacity',6,'idea_set','{"originalIdea":"Children have a greater capacity than adults to learn new sounds, although adults are better at studying grammar.","accurateParaphrases":["Children are naturally better able than adults to learn new sounds, but adults are stronger at studying grammar.","Adults do better at studying grammar, while children have more potential to pick up new sounds.","Although grammar study suits adults more, children have the greater natural ability to learn new sounds."],"meaningInvariants":[{"type":"comparison","value":"children better with sounds, adults better with grammar"}],"distractors":[{"text":"Adults have a greater capacity than children to learn new sounds, although children are better at studying grammar.","misconceptionCategory":"comparison_change"},{"text":"Children have a greater capacity than adults to learn new sounds.","misconceptionCategory":"omitted_information"},{"text":"Children are more interested than adults in new sounds, although adults are better at studying grammar.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_capacity"],"primaryEvidenceTargetId":"vocab_capacity"}'::jsonb,'live'),
('u6_idea_feedback',6,'idea_set','{"originalIdea":"Students improve faster when they receive feedback soon after finishing a task than when they wait a week.","accurateParaphrases":["Learners progress more quickly if comments on their work come straight after the task rather than a week later.","Getting helpful comments promptly after a task helps students to improve faster than waiting seven days does.","A week’s wait for comments slows improvement compared with receiving them soon after the task."],"meaningInvariants":[{"type":"time","value":"soon after the task, not a week later"}],"distractors":[{"text":"Students improve faster when they receive feedback a week after finishing a task than when they receive it immediately.","misconceptionCategory":"time_change"},{"text":"Students improve more slowly when they receive feedback soon after finishing a task than when they wait a week.","misconceptionCategory":"polarity_change"},{"text":"Students improve faster when they receive feedback.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_feedback"],"primaryEvidenceTargetId":"vocab_feedback"}'::jsonb,'live'),
('u6_idea_respond',6,'idea_set','{"originalIdea":"Patients respond better to treatment when they understand why the doctor has chosen it.","accurateParaphrases":["Patients react more positively to treatment if they understand the doctor’s reasons for choosing it.","Understanding the doctor’s reasons for a treatment makes patients react to it more positively.","Patients who are told why a treatment was chosen show a better reaction to it."],"meaningInvariants":[{"type":"cause_effect","value":"understanding the reason leads to a better reaction"}],"distractors":[{"text":"Patients respond worse to treatment when they understand why the doctor has chosen it.","misconceptionCategory":"polarity_change"},{"text":"Patients understand why the doctor has chosen a treatment when they respond better to it.","misconceptionCategory":"cause_effect_change"},{"text":"Patients respond to treatment.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_respond"],"primaryEvidenceTargetId":"vocab_respond"}'::jsonb,'live'),
('u6_idea_hesitation',6,'idea_set','{"originalIdea":"After a long hesitation, the player took the penalty and scored.","accurateParaphrases":["The player was unsure for a long moment, then took the penalty and scored.","Only after a lengthy pause caused by uncertainty did the player take the penalty, and he scored.","The player paused for a long time, full of doubt, before taking the penalty and scoring."],"meaningInvariants":[{"type":"time","value":"long pause before the penalty"}],"distractors":[{"text":"After a brief hesitation, the player took the penalty and scored.","misconceptionCategory":"degree_change"},{"text":"Without any hesitation, the player took the penalty and scored.","misconceptionCategory":"polarity_change"},{"text":"After a long argument, the player took the penalty and scored.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_hesitation"],"primaryEvidenceTargetId":"vocab_hesitation"}'::jsonb,'live'),
('u6_idea_independent',6,'idea_set','{"originalIdea":"Parents can help children to become independent by giving them small responsibilities from an early age.","accurateParaphrases":["Parents can help children learn to manage without constant help by giving them small responsibilities from an early age.","Giving children small duties when they are young helps them to learn to look after themselves.","From an early age, small responsibilities help children to cope without relying heavily on their parents."],"meaningInvariants":[{"type":"cause_effect","value":"small responsibilities lead to self-reliance"}],"distractors":[{"text":"Parents can help children to become independent by doing everything for them from an early age.","misconceptionCategory":"cause_effect_change"},{"text":"Parents can help children to become independent by giving them small responsibilities only when they are adults.","misconceptionCategory":"time_change"},{"text":"Parents can help children to become independent.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_independent"],"primaryEvidenceTargetId":"vocab_independent"}'::jsonb,'live'),
('u6_idea_assumption',6,'idea_set','{"originalIdea":"The scientist realised that her whole experiment depended on an assumption that nobody had tested.","accurateParaphrases":["The scientist realised that her entire experiment relied on an idea, taken as true, that no one had checked.","Her whole experiment rested on a belief that had never been tested, the scientist realised.","The scientist saw that everything in her experiment depended on one untested idea that was simply taken to be true."],"meaningInvariants":[{"type":"quantity","value":"whole experiment depended on one untested belief"}],"distractors":[{"text":"The scientist realised that part of her experiment depended on an assumption that nobody had tested.","misconceptionCategory":"quantity_change"},{"text":"The scientist realised that her whole experiment depended on evidence that nobody had tested.","misconceptionCategory":"meaning_confusion"},{"text":"The scientist realised that her whole experiment depended on an assumption that everybody had tested.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_assumption"],"primaryEvidenceTargetId":"vocab_assumption"}'::jsonb,'live'),
('u6_idea_perspective',6,'idea_set','{"originalIdea":"Travelling abroad gave Ravi a new perspective on his own country, which he now sees as more diverse than he once thought.","accurateParaphrases":["Going overseas gave Ravi a fresh way of looking at his homeland, which he now finds more varied than he used to believe.","After travelling abroad, Ravi sees his own country differently and now finds it more diverse than before.","Spending time in other countries changed how Ravi thinks about his homeland; he now believes it is more varied than he once did."],"meaningInvariants":[{"type":"comparison","value":"more diverse than before"}],"distractors":[{"text":"Travelling abroad gave Ravi a new perspective on his own country, which he now sees as less diverse than he once thought.","misconceptionCategory":"comparison_change"},{"text":"Travelling abroad made Ravi miss his own country, which he now sees as more diverse than he once thought.","misconceptionCategory":"meaning_confusion"},{"text":"Travelling abroad gave Ravi a new perspective on his own country.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_perspective"],"primaryEvidenceTargetId":"vocab_perspective"}'::jsonb,'live'),
('u6_idea_pressure',6,'idea_set','{"originalIdea":"Some students perform worse under pressure, while others perform better.","accurateParaphrases":["Heavy expectations lower some students’ results and raise those of others.","When demands are high, certain students achieve less, while others achieve more.","Stress makes some students do less well, but it helps others to do better."],"meaningInvariants":[{"type":"comparison","value":"worse for some, better for others"}],"distractors":[{"text":"All students perform worse under pressure.","misconceptionCategory":"quantity_change"},{"text":"Some students perform worse under pressure.","misconceptionCategory":"omitted_information"},{"text":"Some students perform worse under pressure, while others perform the same.","misconceptionCategory":"comparison_change"}],"linkedVocabularyIds":["vocab_pressure_6"],"primaryEvidenceTargetId":"vocab_pressure_6"}'::jsonb,'live'),
('u6_idea_prioritise',6,'idea_set','{"originalIdea":"Hospitals prioritise patients with life-threatening injuries, so minor cases often wait for several hours.","accurateParaphrases":["Patients whose lives are in danger are treated first in hospitals, which is why minor cases are often left waiting for hours.","Because hospitals treat the most serious injuries before others, people with minor problems frequently wait for hours.","Minor cases often have a long wait in hospital, since life-threatening injuries are dealt with first."],"meaningInvariants":[{"type":"cause_effect","value":"treating serious cases first causes long waits for minor cases"}],"distractors":[{"text":"Hospitals prioritise patients with minor injuries, so life-threatening cases often wait for several hours.","misconceptionCategory":"polarity_change"},{"text":"Hospitals prioritise patients with life-threatening injuries because minor cases often wait for several hours.","misconceptionCategory":"cause_effect_change"},{"text":"Hospitals prioritise patients with life-threatening injuries.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_prioritise"],"primaryEvidenceTargetId":"vocab_prioritise"}'::jsonb,'live'),
('u6_idea_retain',6,'idea_set','{"originalIdea":"People retain more of a lesson when they teach it to someone else than when they only read it.","accurateParaphrases":["Teaching a lesson to another person helps people to remember more than reading it alone does.","More of a lesson stays in the mind if people explain it to someone than if they simply read it.","Explaining a lesson to someone else is better for remembering it than reading it on your own."],"meaningInvariants":[{"type":"comparison","value":"teaching gives better memory than reading"}],"distractors":[{"text":"People retain less of a lesson when they teach it to someone else than when they only read it.","misconceptionCategory":"polarity_change"},{"text":"People retain the same amount from a lesson whether they teach it to someone else or only read it.","misconceptionCategory":"comparison_change"},{"text":"People retain more of a lesson.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_retain"],"primaryEvidenceTargetId":"vocab_retain"}'::jsonb,'live'),
('u6_idea_summarise',6,'idea_set','{"originalIdea":"Candidates are asked to summarise the passage in fewer than one hundred words, leaving out the examples.","accurateParaphrases":["Candidates must give only the main points of the passage in under a hundred words and omit the examples.","In the exam, the passage has to be reduced to its key ideas, in less than a hundred words, without the examples.","The task is to state the key points of the passage briefly, using fewer than one hundred words and no examples."],"meaningInvariants":[{"type":"quantity","value":"fewer than one hundred words"}],"distractors":[{"text":"Candidates are asked to summarise the passage in more than one hundred words, leaving out the examples.","misconceptionCategory":"quantity_change"},{"text":"Candidates are asked to criticise the passage in fewer than one hundred words, leaving out the examples.","misconceptionCategory":"meaning_confusion"},{"text":"Candidates are asked to summarise the passage.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_summarise"],"primaryEvidenceTargetId":"vocab_summarise"}'::jsonb,'live'),
('u6_idea_coordination',6,'idea_set','{"originalIdea":"Poor coordination between the airline and the airport caused long delays for hundreds of passengers.","accurateParaphrases":["Because the airline and the airport did not work together well, hundreds of passengers faced long delays.","Hundreds of passengers waited a long time because the airline and the airport failed to organise their work together.","A lack of teamwork between the airline and the airport led to long delays for hundreds of passengers."],"meaningInvariants":[{"type":"cause_effect","value":"poor teamwork caused long delays"}],"distractors":[{"text":"Long delays for hundreds of passengers caused poor coordination between the airline and the airport.","misconceptionCategory":"cause_effect_change"},{"text":"Good coordination between the airline and the airport caused long delays for hundreds of passengers.","misconceptionCategory":"polarity_change"},{"text":"Poor coordination between the airline and the airport caused long delays for a few passengers.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_coordination"],"primaryEvidenceTargetId":"vocab_coordination"}'::jsonb,'live'),
('u6_idea_cognitive',6,'idea_set','{"originalIdea":"Regular exercise can improve cognitive abilities such as memory, especially in older adults.","accurateParaphrases":["Memory and other thinking abilities can get better through regular exercise, particularly for older adults.","Older adults in particular may find that regular exercise strengthens abilities like memory and thinking.","Taking exercise regularly may help thinking skills, for example memory, and the effect is strongest in older adults."],"meaningInvariants":[{"type":"degree","value":"especially older adults"}],"distractors":[{"text":"Regular exercise can damage cognitive abilities such as memory, especially in older adults.","misconceptionCategory":"polarity_change"},{"text":"Regular exercise can improve cognitive abilities such as memory, especially in young children.","misconceptionCategory":"meaning_confusion"},{"text":"Regular exercise can improve cognitive abilities.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_cognitive"],"primaryEvidenceTargetId":"vocab_cognitive"}'::jsonb,'live'),
('u6_idea_achievement',6,'idea_set','{"originalIdea":"Finishing the course while caring for two children was a remarkable achievement for her.","accurateParaphrases":["It was an outstanding success for her to complete the course while looking after two children.","Completing the course while raising two children showed what she could do through great effort and ability.","She did something truly impressive by finishing the course while caring for two young children."],"meaningInvariants":[{"type":"degree","value":"remarkable"}],"distractors":[{"text":"Finishing the course while caring for two children was a small achievement for her.","misconceptionCategory":"degree_change"},{"text":"Finishing the course while caring for two children was not an achievement for her.","misconceptionCategory":"polarity_change"},{"text":"Finishing the course was an achievement for her.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_achievement_6"],"primaryEvidenceTargetId":"vocab_achievement_6"}'::jsonb,'live'),
('u6_idea_outcome',6,'idea_set','{"originalIdea":"The outcome of the match was decided by a single goal in the last minute.","accurateParaphrases":["One goal in the final minute decided who won the match.","The result of the game came down to one goal scored right at the end.","A last-minute goal settled how the match finished."],"meaningInvariants":[{"type":"time","value":"one goal in the last minute"}],"distractors":[{"text":"The outcome of the match was decided by a single goal in the first minute.","misconceptionCategory":"time_change"},{"text":"The outcome of the match was decided by three goals in the last minute.","misconceptionCategory":"quantity_change"},{"text":"The outcome of the match was decided by a single goal.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_outcome"],"primaryEvidenceTargetId":"vocab_outcome"}'::jsonb,'live'),
('u6_idea_focus',6,'idea_set','{"originalIdea":"Students who focus on one task at a time usually make fewer mistakes than those who switch between tasks.","accurateParaphrases":["Working on a single task at a time usually leads to fewer mistakes than moving between tasks.","Fewer mistakes are usually made by students who give full attention to one task at a time than by those who keep changing tasks.","Those who keep their attention on one job at once tend to make fewer errors than students who jump between jobs."],"meaningInvariants":[{"type":"comparison","value":"one task at a time gives fewer mistakes"}],"distractors":[{"text":"Students who focus on one task at a time usually make more mistakes than those who switch between tasks.","misconceptionCategory":"polarity_change"},{"text":"Students who focus on one task at a time make the same number of mistakes as those who switch between tasks.","misconceptionCategory":"comparison_change"},{"text":"Students who focus on one task at a time usually make fewer mistakes.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_focus"],"primaryEvidenceTargetId":"vocab_focus"}'::jsonb,'live'),
('u6_idea_memorise',6,'idea_set','{"originalIdea":"It is easier to memorise a long number if you divide it into short groups.","accurateParaphrases":["Splitting a long number into short groups makes it easier to learn by heart.","A long number is easier to learn exactly if it is divided into small groups.","Dividing a long number into short groups helps you to learn it so that you can repeat it exactly."],"meaningInvariants":[{"type":"cause_effect","value":"dividing into groups makes learning easier"}],"distractors":[{"text":"It is harder to memorise a long number if you divide it into short groups.","misconceptionCategory":"polarity_change"},{"text":"It is easier to divide a long number into short groups if you memorise it.","misconceptionCategory":"cause_effect_change"},{"text":"It is easier to memorise a long number.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_memorise"],"primaryEvidenceTargetId":"vocab_memorise"}'::jsonb,'live'),
('u6_idea_insight',6,'idea_set','{"originalIdea":"Reading the manager’s emails gave the investigator real insight into why the project had failed.","accurateParaphrases":["The investigator came to understand much better why the project had failed after reading the manager’s emails.","By reading the manager’s emails, the investigator gained a clear understanding of the reasons for the project’s failure.","The manager’s emails helped the investigator to see more deeply why the project failed."],"meaningInvariants":[{"type":"cause_effect","value":"reading the emails led to deeper understanding"}],"distractors":[{"text":"The investigator read the manager’s emails because he already had insight into why the project had failed.","misconceptionCategory":"cause_effect_change"},{"text":"Reading the manager’s emails gave the investigator no insight into why the project had failed.","misconceptionCategory":"polarity_change"},{"text":"Reading the manager’s emails gave the investigator real information about the cost of the project.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_insight"],"primaryEvidenceTargetId":"vocab_insight"}'::jsonb,'live'),
